# Generated by build.py from recipe.yml for recipe mqtts-log-in-over-tls. Do not edit.
set -e
cd "$(dirname "$0")"
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --cert server.pem --key server.key --user alice:s3cret --topic "home/#;retain" mqtts://127.0.0.1:8080/ &
sleep 1
curl -s --cacert server.pem -u alice:s3cret -d 21.5 mqtts://127.0.0.1:8080/home/temp --next -s --cacert server.pem -u alice:s3cret mqtts://127.0.0.1:8080/home/temp
kill $(jobs -p)
